self.addEventListener('install', event => {
  // Never mix an old HTTP-cached index with new, content-addressed scripts.
  // A deployment in transition must fail installation and retain the working shell.
  const requests = SHELL_FILES.map(path => new Request(new URL(path, self.registration.scope).href, {cache:'reload', integrity:SHELL_INTEGRITY[path]}));
  event.waitUntil(caches.open(CACHE_NAME).then(cache => cache.addAll(requests)));
  // No skipWaiting: an update must not interrupt an open editing session.
});
self.addEventListener('activate', event => {
  event.waitUntil(caches.keys().then(names => Promise.all(names.filter(name => name.startsWith(CACHE_PREFIX) && name !== CACHE_NAME).map(name => caches.delete(name)))).then(() => self.clients.claim()));
});
self.addEventListener('fetch', event => {
  const request = event.request;
  if (request.method !== 'GET') return;
  const url = new URL(request.url);
  if (url.origin !== self.location.origin) return;
  url.search = ''; url.hash = '';
  if (!SHELL_URLS.has(url.href)) return;
  event.respondWith(caches.open(CACHE_NAME).then(async cache => {
    const cached = await cache.match(url.href);
    if (cached) return cached;
    return fetch(request); // No runtime cache: file/API responses cannot enter the shell cache.
  }));
});
